import {hasSensitive} from './admin-permissions.mjs';
import {leaveLabels,leaveActions} from './leave-contract.mjs';
export function createLeaveViews({api,h,showPanel,localTime,writable,getUser,onEdit,onAction}){
 const fmt=v=>v?localTime(v):'未提供';
 async function detail(id,offset=0){await showPanel('请假申请',async signal=>{
  const [r,history]=await Promise.all([api.leaveDetail(id,signal),api.leaveHistory(id,offset,signal)]),employee=getUser().role==='employee';
  let actions='';if(writable&&(employee||hasSensitive(getUser(),'personnel'))){if(r.status==='pending')actions=employee?`<button class="primary" data-leave-edit="${h(id)}">修改申请</button><button class="secondary" data-leave-action="withdraw" data-leave-id="${h(id)}">撤回申请</button>`:`<button class="primary" data-leave-action="decision" data-decision="approved" data-leave-id="${h(id)}">批准</button><button class="secondary" data-leave-action="decision" data-decision="rejected" data-leave-id="${h(id)}">驳回并说明</button>`;else if(!employee&&r.status==='approved')actions=`<button class="secondary" data-leave-action="revoke" data-leave-id="${h(id)}">撤销批准</button>`;}
  return `<div class="dialog-header"><h2>${h(r.memberName||'请假申请')}</h2><button class="icon-button" data-attendance-close aria-label="关闭请假详情">×</button></div><div class="detail-meta"><span class="type-tag">${h(leaveLabels[r.status])}</span><span>${h(r.leave_type)}</span></div><p>${h(fmt(r.starts_at))} — ${h(fmt(r.ends_at))}（北京时间）</p><p class="preserve-text">申请原因：${h(r.reason)}</p>${r.reviewed_at?`<p>审核时间：${h(fmt(r.reviewed_at))}</p><p class="preserve-text">审核说明：${h(r.review_note)}</p>`:''}${r.withdrawn_at?`<p>撤回时间：${h(fmt(r.withdrawn_at))}</p><p class="preserve-text">撤回原因：${h(r.withdrawal_reason)}</p>`:''}${r.revoked_at?`<p>撤销时间：${h(fmt(r.revoked_at))}</p><p class="preserve-text">撤销原因：${h(r.revoke_note)}</p>`:''}<div class="action-row">${actions}</div><p class="muted">这里只保存请假时间段，不覆盖上下班时间，不自动折算工资。</p><h3>修改与审核历史</h3>${history.rows.map(e=>`<article class="observation"><b>${h(leaveActions[e.action])}</b><p>${h(e.actor_name)} · ${h(fmt(e.created_at))}</p><p>${h(e.after_value.leave_type)} · ${h(fmt(e.after_value.starts_at))} — ${h(fmt(e.after_value.ends_at))}</p>${e.before_value?`<p>此前：${h(e.before_value.leave_type)} · ${h(fmt(e.before_value.starts_at))} — ${h(fmt(e.before_value.ends_at))} · ${h(leaveLabels[e.before_value.status])}</p>`:''}<p class="preserve-text">${h(e.action==='withdrawn'?e.after_value.withdrawal_reason:e.action==='revoked'?e.after_value.revoke_note:['approved','rejected'].includes(e.action)?e.after_value.review_note:e.after_value.reason)}</p></article>`).join('')}<div class="pager"><button class="secondary" data-leave-detail="${h(id)}" data-history-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页</button><span>${history.total?offset+1+'–'+(offset+history.rows.length)+' / '+history.total:'0 条'}</span><button class="secondary" data-leave-detail="${h(id)}" data-history-offset="${offset+50}" ${offset+history.limit>=history.total?'disabled':''}>下一页</button></div>`;
 });}
 document.addEventListener('click',e=>{const d=e.target.closest('button[data-leave-detail]'),edit=e.target.closest('button[data-leave-edit]'),action=e.target.closest('button[data-leave-action]');if(d)detail(d.dataset.leaveDetail,Number(d.dataset.historyOffset||0));if(edit)onEdit(edit.dataset.leaveEdit||undefined);if(action)onAction(action.dataset.leaveId,action.dataset.leaveAction,action.dataset.decision);});
 return {row:r=>`<button class="asset-row" data-leave-detail="${h(r.id)}"><span><b>${h(r.memberName||'本人')}</b><small>${h(r.leave_type)} · ${h(leaveLabels[r.status])}</small></span><span><b>${h(fmt(r.starts_at))} — ${h(fmt(r.ends_at))}</b><small>${h(r.reason)}</small></span><span class="task-arrow">›</span></button>`};
}
